/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-scroll-area {
  min-width: 0;
  max-width: 100%;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-body-size);
  line-height: var(--ui-type-body-line-height);
  letter-spacing: var(--ui-type-body-letter-spacing);
}
:where([data-moru-registry]) .ui-scroll-area {
  position: relative;
  overflow: hidden;
  border: var(--ui-border-width) solid var(--ui-border);
  border-radius: calc(var(--ui-radius) + 4px);
  background: var(--ui-surface);
}
:where([data-moru-registry]) .ui-scroll-viewport {
  width: 100%;
  height: 100%;
  max-height: inherit;
  border-radius: inherit;
  outline: none;
  overscroll-behavior: contain;
}
:where([data-moru-registry]) .ui-scroll-viewport:focus-visible {
  outline: 2px solid var(--ui-focus-ring);
  outline-offset: -3px;
}
:where([data-moru-registry]) .ui-scroll-content {
  min-width: 100%;
}
:where([data-moru-registry]) .ui-scroll-bar {
  display: flex;
  padding: 3px;
  margin: 2px;
  user-select: none;
  opacity: 0;
  transition: opacity var(--ui-duration);
}
:where([data-moru-registry]) .ui-scroll-bar[data-orientation='vertical'] {
  width: 12px;
}
:where([data-moru-registry]) .ui-scroll-bar[data-orientation='horizontal'] {
  height: 12px;
}
:where([data-moru-registry]) .ui-scroll-area:hover .ui-scroll-bar,
:where([data-moru-registry]) .ui-scroll-area:focus-within .ui-scroll-bar,
:where([data-moru-registry]) .ui-scroll-bar[data-scrolling] {
  opacity: 1;
}
:where([data-moru-registry]) .ui-scroll-thumb {
  flex: 1;
  border-radius: 99px;
  background: var(--ui-muted);
  opacity: 0.65;
}
:where([data-moru-registry]) .ui-scroll-corner {
  background: var(--ui-surface);
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-scroll-bar {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { forwardRef, type ComponentPropsWithoutRef } from 'react'
import { ScrollArea as BaseScrollArea } from '@base-ui/react/scroll-area'
import { cn } from './_lib/cn'
import './scroll-area.css'

export interface ScrollAreaProps extends ComponentPropsWithoutRef<'div'> {
  orientation?: 'vertical' | 'horizontal' | 'both'
  viewportClassName?: string
}

/** Give the root a height (or max-height) to constrain its viewport. */
export const ScrollArea = forwardRef<HTMLDivElement, ScrollAreaProps>(function ScrollArea(
  {
    children,
    className,
    viewportClassName,
    orientation = 'vertical',
    onScroll,
    'aria-label': labelProp,
    ...props
  },
  ref,
) {
  const { t } = useI18n()
  const label = labelProp ?? t('스크롤 영역')

  return (
    <BaseScrollArea.Root {...props} className={cn('ui-scroll-area', className)}>
      <BaseScrollArea.Viewport
        ref={ref}
        className={cn('ui-scroll-viewport', viewportClassName)}
        role="region"
        aria-label={label}
        tabIndex={0}
        onScroll={onScroll}
      >
        <BaseScrollArea.Content className="ui-scroll-content">{children}</BaseScrollArea.Content>
      </BaseScrollArea.Viewport>
      {orientation !== 'horizontal' && <ScrollBar orientation="vertical" />}
      {orientation !== 'vertical' && <ScrollBar orientation="horizontal" />}
      {orientation === 'both' && <BaseScrollArea.Corner className="ui-scroll-corner" />}
    </BaseScrollArea.Root>
  )
})

export function ScrollBar({
  className,
  ...props
}: Omit<ComponentPropsWithoutRef<typeof BaseScrollArea.Scrollbar>, 'className'> & {
  className?: string
}) {
  return (
    <BaseScrollArea.Scrollbar {...props} className={cn('ui-scroll-bar', className)}>
      <BaseScrollArea.Thumb className="ui-scroll-thumb" />
    </BaseScrollArea.Scrollbar>
  )
}
